	let renderWidth = 1;
	let renderHeight = 1;
	let sceneWidth = 1;
	let sceneHeight = 1;
	let prepassWidth = 1;
	let prepassHeight = 1;
	let bloomWidth = 1;
	let bloomHeight = 1;
	let currentDpr = 1;
	let targetAllocationScale = 1;
	let allocationScaleReason: string | null = null;
	let lastAllocationFailure: string | null = null;

