            if (dr_in < 2.0)  color = mix(color, vec4(80.0/255.0, 125.0/255.0, 1.0, 1.0), 1.0 - smoothstep(1.0, 2.0, dr_in));
        }

        // CTC 边界 (以多项式隐函数零点逼近)
        float G = (r2 + a2) * (r2 + a2*cosT2) + a2*sinT2*(2.0*M*r_px - Q2);
