                s0.X = X; s0.P = P_cov; k1 = GetDerivativesAnalytic(s0, PhysicalSpinA, PhysicalQ, GravityFade, isoutgoing, geo); CurrentDr = dot(geo.grad_r, k1.X.xyz); shiftinout = true;
